// Keep ordinary output payloads unchanged. Only an explicit capture import
// persists the resolved full-body source (not a reconstruction from prose).
const fullBodySources = new WeakMap();
const IDENTITY_KEYS = new Set(['bodyTypeId', 'facialFeaturesId', 'skinDetailsId', 'hairstyleId', 'hairStylingStateId', 'hairColorId']);
const WARDROBE_KEY = /^(?:specialOutfit|completeLookPalette|outfitPreset|top|dress|pants|skirt|bottom|outerwear|legwear|shoes|headphones|faceCovering|headAccessory|eyewear|earrings|nosePiercing|lipPiercing|neckAccessory|wristAccessory|ring|waistAccessory).*Id$/;
export const isImportedPersonKey = key => IDENTITY_KEYS.has(key) || WARDROBE_KEY.test(key) && !/[AB](?:Color|Pattern|Fit|Opening|Styling)?Id$/.test(key);
const copy = value => JSON.parse(JSON.stringify(value));
const selectionOnly = value => Object.fromEntries(Object.entries(value || {}).filter(([key, entry]) =>
  isImportedPersonKey(key) && (typeof entry === 'string' || Array.isArray(entry) && entry.every(id => typeof id === 'string'))));
const record = value => value && typeof value === 'object' && !Array.isArray(value);
const sourceItem = item => record(item) && typeof item.id === 'string' && typeof item.en === 'string' && record(item.meta);

export function normalizeImportedPerson(value) {
  if (!record(value) || value.version !== 1 || typeof value.fullBodyPrompt !== 'string' || !value.fullBodyPrompt.trim()
    || !Array.isArray(value.character) || !value.character.every(sourceItem)
    || !Array.isArray(value.wardrobe) || !value.wardrobe.every(sourceItem)
    || !record(value.wardrobeColors) || !record(value.selection) || !record(value.rawSelection)) return null;
  // Palette records also carry nested top/bottom colors and need not have item metadata.
  if (!Object.values(value.wardrobeColors).every(item => item === null || record(item) && typeof item.id === 'string')) return null;
  return copy({ version: 1, character: value.character, wardrobe: value.wardrobe, wardrobeColors: value.wardrobeColors,
    selection: selectionOnly(value.selection), rawSelection: selectionOnly(value.rawSelection), fullBodyPrompt: value.fullBodyPrompt });
}

export function registerFullBodyImportSource(prompt, { character, wardrobe, wardrobeColors, locks }) {
  const fullBodyPrompt = prompt.extraPrompts.find(entry => entry.id === 'full-body-character')?.text;
  const snapshot = normalizeImportedPerson({ version: 1, character, wardrobe, wardrobeColors: copy(wardrobeColors),
    selection: prompt.selection, rawSelection: locks, fullBodyPrompt });
  if (snapshot) fullBodySources.set(prompt.structured, snapshot);
}

export function getFullBodyImportSource(prompt) {
  const source = prompt?.structured && fullBodySources.get(prompt.structured);
  return source ? copy(source) : null;
}

export function prepareCaptureEntry(profile, standardPrompt) {
  return { ...profile, availablePerson: getFullBodyImportSource(standardPrompt) };
}

export function importCapturePerson(profile) {
  return { ...profile, personSource: 'full-body', importedPerson: normalizeImportedPerson(profile.availablePerson) || normalizeImportedPerson(profile.importedPerson) };
}

export function activeImportedPerson(locks) {
  return locks.captureMode === 'observation' && locks.observationCapture?.personSource === 'full-body'
    ? normalizeImportedPerson(locks.observationCapture.importedPerson) : null;
}

export function importedPersonLocks(person) {
  return { ...person.selection, subjectCount: '1', characterProfileId: 'none', specialSubjectId: 'none',
    characterCardHairVariantId: 'default', characterCardEyewearMode: 'default', characterCardWardrobeMode: 'full-default',
    characterCardWardrobeLayerIds: [], characterCardPromptOverride: '' };
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createEmptyLocks, generatePrompts, getLockControls, normalizeLocks } from './engine.js';
import { createSeededRandom } from './engineRandom.js';
import { buildWorkspaceSummary } from './page1WorkspaceSummary.js';
import { getFullBodyImportSource, prepareCaptureEntry, importCapturePerson, normalizeImportedPerson } from './observationCaptureImport.js';
import { CAPTURE_GROUPS, resolveCapture, rerollCapture } from './observationCaptureMode.js';
import { PROMPT_OUTPUT_CONTRACTS, validatePromptOutputContract } from './engine/promptOutputContracts.js';
import { buildRestoreLocks, serializeFavoritePrompt, deserializeFavoritePrompt, buildMarkdownExport, parseExportedMarkdownPrompt } from '../features/saved-cards/cardCodec.js';

const controls = getLockControls();
const sourceLocks = () => ({ ...createEmptyLocks(), subjectCount: '1', characterProfileId: 'none', specialSubjectId: 'none', fixedCompositionSetId: 'none',
  framingId: controls.find(c => c.key === 'framingId').options.find(o => o.zh.startsWith('全身鏡頭')).id });
const generate = (locks, seed = 'capture-person-import') => generatePrompts(1, locks, [], { random: createSeededRandom(seed) })[0];
function imported(locks, source) {
  return { ...locks, captureMode: 'observation', observationCapture: importCapturePerson(prepareCaptureEntry(resolveCapture({}).profile, source)) };
}
const outputs = p => [p.grokPrompt, p.zImagePrompt, p.midjourneyPrompt, p.nanoBananaPrompt, ...p.extraPrompts.map(x => x.text)];

test('imported summaries omit dormant duo fields and use the same resolved person', () => {
  const locks = { ...sourceLocks(), hairColorAId: controls.find(c => c.key === 'hairColorAId').options.find(o => o.zh === '自然黑').id,
    topAId: controls.find(c => c.key === 'topAId').options.find(o => o.en !== 'none').id };
  const next = imported(locks, generate(locks));
  const person = next.observationCapture.importedPerson;
  assert.equal(person.selection.topAId, undefined);
  assert.equal(person.selection.hairColorAId, undefined);
  const actual = buildWorkspaceSummary(next, controls);
  const expected = buildWorkspaceSummary(person.selection, controls);
  assert.equal(actual.character.summary, expected.character.summary);
  assert.equal(actual.wardrobe.summary, expected.wardrobe.summary);
});

test('full-body import captures resolved data, colors and original settings without altering the source', () => {
  const locks = sourceLocks();
  const source = generate(locks);
  const before = JSON.stringify(source);
  const snapshot = getFullBodyImportSource(source);
  assert.ok(snapshot);
  assert.equal(snapshot.fullBodyPrompt, source.extraPrompts.find(x => x.id === 'full-body-character').text);
  assert.deepEqual(snapshot.wardrobe, source.structured.Wardrobe);
  assert.equal(snapshot.rawSelection.hairstyleId, locks.hairstyleId);
  assert.equal(snapshot.selection.hairstyleId, source.selection.hairstyleId);
  const next = imported(locks, source);
  const result = generate(next);
  assert.ok(result);
  assert.deepEqual(result.structured.Wardrobe, source.structured.Wardrobe);
  assert.equal(result.extraPrompts.find(x => x.id === 'full-body-character').text, snapshot.fullBodyPrompt);
  assert.equal(JSON.stringify(source), before);
});

test('capture reroll preserves imported identity, wardrobe and full-body output across seeds', () => {
  const locks = sourceLocks();
  const source = generate(locks);
  const next = imported(locks, source);
  const first = generate(next);
  for (let i = 0; i < 12; i++) {
    next.observationCapture = rerollCapture(next.observationCapture).profile;
    const result = generate(next, `other-${i}`);
    assert.deepEqual(result.structured.Character.slice(0, -1), first.structured.Character.slice(0, -1));
    assert.deepEqual(result.structured.Wardrobe, first.structured.Wardrobe);
    assert.equal(result.extraPrompts[1].text, first.extraPrompts[1].text);
  }
});

test('six outputs survive JSON, markdown and reload while dormant standard choices are preserved', () => {
  const locks = { ...sourceLocks(), poseBaseId: 'sitting' };
  const next = imported(locks, generate(locks));
  const first = generate(next);
  for (const restored of [
    normalizeLocks(JSON.parse(JSON.stringify(next))),
    normalizeLocks(buildRestoreLocks(deserializeFavoritePrompt(serializeFavoritePrompt(first)).selection, controls)),
    normalizeLocks(parseExportedMarkdownPrompt(buildMarkdownExport(first), controls, 'import-test').selection),
  ]) {
    assert.deepEqual(outputs(generate(restored)), outputs(first));
    assert.equal(restored.poseBaseId, locks.poseBaseId);
    assert.equal(restored.hairstyleId, locks.hairstyleId);
  }
  assert.deepEqual(outputs(generate({ ...next, captureMode: 'standard' })), outputs(generate(locks)));
});

test('missing source cannot generate, reimport is explicit, and unsupported sources cannot be used', () => {
  const locks = sourceLocks();
  const source = generate(locks);
  const first = imported(locks, source);
  const different = generate(locks, 'different-person');
  const prepared = prepareCaptureEntry(first.observationCapture, different);
  assert.deepEqual(prepared.importedPerson, first.observationCapture.importedPerson);
  assert.notDeepEqual(importCapturePerson(prepared).importedPerson, prepared.importedPerson);
  assert.equal(getFullBodyImportSource(generate({ ...locks, subjectCount: '2' })), null);
  assert.equal(getFullBodyImportSource(generate(first)), null);
  assert.equal(generate({ ...locks, captureMode: 'observation', observationCapture: { personSource: 'full-body' } }), undefined);
  assert.equal(getFullBodyImportSource({ ...source, structured: {} }), null);
  assert.deepEqual(importCapturePerson({ ...first.observationCapture, availablePerson: null }).importedPerson, first.observationCapture.importedPerson);
});

const byZh = (key, label) => controls.find(c => c.key === key).options.find(o => o.zh.includes(label))?.id;
function silentLocks() {
  const locks = sourceLocks();
  for (const c of controls) {
    const none = c.options?.find(o => o.zh === '全無');
    if (none && !c.required && c.key !== 'framingId') locks[c.key] = none.id;
  }
  return locks;
}

test('explicit face, skin, hair and body survive import; main GPT body omission and full-body retention remain', () => {
  const locks = silentLocks();
  for (const key of ['facialFeaturesId', 'skinDetailsId', 'hairstyleId', 'hairColorId']) {
    locks[key] = controls.find(c => c.key === key).options.find(o => o.en && o.zh !== '全無' && o.id !== 'random').id;
  }
  locks.bodyTypeId = byZh('bodyTypeId', '豐胸纖腰沙漏');
  locks.topId = byZh('topId', '領帶襯衫');
  locks.topColorId = byZh('topColorId', '紅色');
  const source = generate(locks);
  const result = generate(imported(locks, source));
  for (const item of getFullBodyImportSource(source).character.filter(item => !item.id.includes('body-type') && item.zh !== '全無')) {
    assert.ok(result.grokPrompt.toLowerCase().includes(item.en.toLowerCase()), item.zh);
  }
  assert.doesNotMatch(result.grokPrompt, /I–K cup bust/);
  assert.doesNotMatch(result.extraPrompts[0].text, /I–K cup bust/);
  assert.match(result.extraPrompts[1].text, /I–K cup bust/);
  assert.match(result.grokPrompt, /red/);
});

test('none stays silent, close-up source retains hidden clothing and source snapshots are immutable copies', () => {
  for (const framing of ['全身鏡頭', '全臉傾斜特寫']) {
    const locks = { ...silentLocks(), framingId: byZh('framingId', framing), pantsId: byZh('pantsId', '牛仔'), shoesId: byZh('shoesId', 'adizero') };
    const source = generate(locks);
    const person = getFullBodyImportSource(source);
    const next = imported({ ...locks, framingId: sourceLocks().framingId }, source);
    const result = generate(next);
    assert.deepEqual(result.structured.Wardrobe, source.structured.Wardrobe);
    assert.equal(result.extraPrompts[1].text, person.fullBodyPrompt);
    assert.equal(result.structured.Character.filter(x => /hairstyle|hair-color|facial-features/.test(x.id)).every(x => x.zh === '全無'), true);
    person.wardrobe.length = 0;
    assert.notDeepEqual(person, getFullBodyImportSource(source));
  }
});

test('imported source passes six-output contracts for every capture scene and supported framing', () => {
  const locks = { ...silentLocks(), topId: byZh('topId', '領帶襯衫'), topColorId: byZh('topColorId', '紅色'), pantsId: byZh('pantsId', '牛仔') };
  const source = generate(locks);
  for (const scene of CAPTURE_GROUPS[0].options) for (const framing of ['全身鏡頭', '中景鏡頭', '牛仔中景']) {
    const next = imported({ ...locks, framingId: byZh('framingId', framing) }, source);
    next.observationCapture = { ...next.observationCapture, selected: { scene: scene.id }, fixed: { scene: true } };
    const p = generate(next);
    for (const [field, contract] of Object.entries(PROMPT_OUTPUT_CONTRACTS)) {
      const value = contract.source.kind === 'field' ? p[contract.source.key] : p.extraPrompts.find(x => x.id === contract.source.id)?.text;
      assert.deepEqual(validatePromptOutputContract(field, value || '', { mode: 'single' }), [], `${scene.id}/${framing}/${field}`);
    }
  }
});

test('invalid imported records fail closed and card selection cannot leak into imported identity', () => {
  const locks = silentLocks();
  const next = imported(locks, generate(locks));
  const card = controls.find(c => c.key === 'characterProfileId').options.find(o => o.specialSubject === 'character-profile');
  assert.deepEqual(outputs(generate({ ...next, characterProfileId: card.id })), outputs(generate(next)));
  for (const invalid of [null, {}, { ...next.observationCapture.importedPerson, version: 99 }, { ...next.observationCapture.importedPerson, wardrobe: ['bad'] }]) {
    assert.equal(normalizeImportedPerson(invalid), null);
    assert.equal(generate({ ...next, observationCapture: { ...next.observationCapture, importedPerson: invalid } }), undefined);
  }
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { createEmptyLocks, createSeededRandom, generatePrompts, getLockControls, normalizeLocks } from '../../lib/engine.js';
import { transitionPage1Locks } from './lockTransitions.js';
import { reconcilePage1SingleWardrobeLocks } from './page1WardrobeExclusivity.js';
import { buildAllNoneLocks } from './page1Selectors.js';
import { buildRestoreLocks, buildMarkdownExport, parseExportedMarkdownPrompt, serializeFavoritePrompt, deserializeFavoritePrompt } from '../saved-cards/cardCodec.js';
import { getFullBodyImportSource, prepareCaptureEntry, importCapturePerson } from '../../lib/observationCaptureImport.js';
import { resolveCapture } from '../../lib/observationCaptureMode.js';
const controls = getLockControls();
const options = key => controls.find(c => c.key === key).options;
const concrete = key => options(key).filter(o => o.id && !['none', 'random'].includes(o.id) && o.zh !== '全無');
const item = (key, text) => options(key).find(o => o.zh.includes(text));
const empty = () => ({ ...buildAllNoneLocks(controls, createEmptyLocks()), subjectCount: '1', framingId: item('framingId', '全身鏡頭').id });
const special = () => ({ ...empty(), specialOutfitId: item('specialOutfitId', '紅色亮面膠帶').id, completeLookPaletteId: 'silver-metallic' });
const transition = (previousLocks, candidateLocks, restoringSelection = false) => transitionPage1Locks({ previousLocks, candidateLocks, restoringSelection, lockControls: controls });
const generate = locks => generatePrompts(1, locks, [], { random: createSeededRandom('a2-special-palette') })[0];

test('A2 all 90 single special outfits preserve all nine palettes and explicit none through manual, restore and unrelated updates', () => {
  assert.equal(concrete('specialOutfitId').length, 90);
  assert.equal(concrete('completeLookPaletteId').length, 9);
  for (const outfit of concrete('specialOutfitId')) for (const palette of options('completeLookPaletteId')) {
    const next = { ...empty(), specialOutfitId: outfit.id, completeLookPaletteId: palette.id };
    for (const [previous, candidate, restore] of [
      [{ ...next, completeLookPaletteId: 'none' }, next, false],
      [empty(), normalizeLocks(buildRestoreLocks(next, controls)), true],
      [next, { ...next, hairColorId: 'red' }, false],
    ]) assert.equal(transition(previous, candidate, restore).completeLookPaletteId, palette.id, outfit.id + palette.id);
  }
});

test('A2 preserving a special palette does not retain covered clothes, layers or accessories', () => {
  const dirty = special();
  for (const key of ['outfitPresetId', 'dressId', 'topId', 'pantsId', 'outerwearId', 'shoesId', 'headAccessoryId', 'eyewearId', 'topBottomPaletteId']) dirty[key] = concrete(key)[0].id;
  const next = transition(empty(), dirty);
  assert.equal(next.completeLookPaletteId, dirty.completeLookPaletteId);
  assert.equal(next.specialOutfitId, dirty.specialOutfitId);
  for (const control of controls.filter(c => c.section === 'wardrobe' && !['specialOutfitId', 'specialOutfitAId', 'specialOutfitBId', 'completeLookPaletteId'].includes(c.key))) {
    assert.equal(next[control.key], control.options.find(o => o.zh === '全無')?.id || '', control.key);
  }
});

test('A2 switching special outfits, explicit palette none and reload retain the intended complete-look state', () => {
  const previous = special();
  const changed = transition(previous, { ...previous, specialOutfitId: concrete('specialOutfitId')[0].id });
  assert.equal(changed.completeLookPaletteId, previous.completeLookPaletteId);
  const loaded = reconcilePage1SingleWardrobeLocks({ previousLocks: createEmptyLocks(), candidateLocks: normalizeLocks(JSON.parse(JSON.stringify(changed))), lockControls: controls });
  assert.equal(transition(loaded, { ...loaded, hairColorId: 'red' }).completeLookPaletteId, previous.completeLookPaletteId);
  assert.equal(transition(changed, { ...changed, completeLookPaletteId: 'none' }).completeLookPaletteId, 'none');
  assert.equal(transition(previous, buildAllNoneLocks(controls, previous)).completeLookPaletteId, 'none');
  const separates = transition(previous, { ...empty(), topId: concrete('topId')[0].id, completeLookPaletteId: previous.completeLookPaletteId });
  assert.equal(separates.completeLookPaletteId, 'none');
});

test('A2 duo A and B special palettes remain isolated and the other person stays intact', () => {
  for (const role of ['A', 'B']) for (const palette of concrete('completeLookPaletteId')) {
    const other = role === 'A' ? 'B' : 'A';
    const previous = { ...empty(), subjectCount: '2', ['top' + other + 'Id']: concrete('top' + other + 'Id')[0].id, ['completeLookPalette' + other + 'Id']: 'cream-neutral' };
    const next = transition(previous, { ...previous, ['specialOutfit' + role + 'Id']: concrete('specialOutfit' + role + 'Id')[0].id, ['completeLookPalette' + role + 'Id']: palette.id }, true);
    assert.equal(next['completeLookPalette' + role + 'Id'], palette.id);
    assert.equal(next['completeLookPalette' + other + 'Id'], previous['completeLookPalette' + other + 'Id']);
    assert.equal(next['top' + other + 'Id'], previous['top' + other + 'Id']);
  }
});

test('A2 JSON and complete Markdown retain original outputs and special palette after apply', () => {
  const p = generate(special());
  const json = serializeFavoritePrompt(p), before = JSON.stringify(json);
  for (const restored of [deserializeFavoritePrompt(json), parseExportedMarkdownPrompt(buildMarkdownExport(p), controls, 'a2-special')]) {
    assert.equal(restored.grokPrompt, p.grokPrompt);
    assert.equal(restored.selection.completeLookPaletteId, 'silver-metallic');
    const next = transition(empty(), normalizeLocks(buildRestoreLocks(restored.selection, controls)), true);
    assert.equal(next.completeLookPaletteId, 'silver-metallic');
    assert.ok(generate(next).extraPrompts.find(x => x.id === 'full-body-character').text.includes('outfit palette: ' + options('completeLookPaletteId').find(o => o.id === 'silver-metallic').en));
  }
  assert.equal(JSON.stringify(json), before);
});

test('A2 special capture source keeps its palette and frozen reference across capture generation', () => {
  const locks = transition(empty(), special()), p = generate(locks);
  const profile = importCapturePerson(prepareCaptureEntry(resolveCapture({ seed: 41 }).profile, p));
  const person = getFullBodyImportSource(p);
  assert.equal(person.selection.completeLookPaletteId, 'silver-metallic');
  assert.deepEqual(profile.importedPerson, person);
  const frozen = JSON.stringify(person);
  const capture = generate({ ...locks, captureMode: 'observation', observationCapture: profile });
  assert.equal(capture.extraPrompts.find(x => x.id === 'full-body-character').text, person.fullBodyPrompt);
  assert.equal(JSON.stringify(person), frozen);
});

test('A2 deferred split-dress restore and paired-color capture limits remain unchanged', () => {
  const locks = { ...empty(), dressId: concrete('dressId')[0].id, topBottomPaletteId: concrete('topBottomPaletteId')[0].id };
  assert.equal(buildRestoreLocks(locks, controls).topBottomPaletteId, 'none');
  assert.equal(getFullBodyImportSource(generate(locks)), null);
  assert.ok(getFullBodyImportSource(generate({ ...locks, topBottomPaletteId: 'none' })));
});

import assert from 'node:assert/strict';
import test from 'node:test';
import {readFileSync,writeFileSync,mkdirSync,mkdtempSync,rmSync,existsSync} from 'node:fs';
import {join,dirname} from 'node:path';
import {tmpdir} from 'node:os';
import {createHash} from 'node:crypto';
import {SPECIAL_PALETTE_ROOT as root,SPECIAL_PALETTE_REVIEW as review,restorePreA2SpecialPaletteFiles as restore} from '../../../../scripts/lib/a2SpecialPaletteReplay.mjs';
const hash=b=>createHash('sha256').update(b).digest('hex');
test('A2 special palette history restores exact fixed transition and is idempotent only in isolated copies',()=>{
 assert.throws(()=>restore(root),/isolated/);
 const dir=mkdtempSync(join(tmpdir(),'special-palette-inverse-'));
 try{
  for(const p of [review.path,...Object.keys(review.newTests)]){mkdirSync(dirname(join(dir,p)),{recursive:true});writeFileSync(join(dir,p),readFileSync(join(root,p)));}
  restore(dir);assert.equal(hash(readFileSync(join(dir,review.path))),review.beforeHash);
  for(const p of Object.keys(review.newTests))assert.equal(existsSync(join(dir,p)),false);
  restore(dir);assert.equal(hash(readFileSync(join(dir,review.path))),review.beforeHash);
 }finally{rmSync(dir,{recursive:true,force:true});}
});
test('A2 special palette inverse rejects missing, changed, mixed and Git inputs before writing',()=>{
 const dir=mkdtempSync(join(tmpdir(),'special-palette-invalid-')),paths=[review.path,...Object.keys(review.newTests)];
 const seed=()=>{for(const p of paths){mkdirSync(dirname(join(dir,p)),{recursive:true});writeFileSync(join(dir,p),readFileSync(join(root,p)));}};
 const snapshot=()=>paths.map(p=>existsSync(join(dir,p))?readFileSync(join(dir,p)):null);
 try{
  for(const p of paths)for(const type of ['missing','changed']){seed();if(type==='missing')rmSync(join(dir,p));else writeFileSync(join(dir,p),readFileSync(join(dir,p),'utf8')+'\n// unknown');const before=snapshot();assert.throws(()=>restore(dir),/rejects|missing/);assert.deepEqual(snapshot(),before);}
  seed();writeFileSync(join(dir,review.path),readFileSync(join(dir,review.path),'utf8').replace(review.after,review.before));let before=snapshot();assert.throws(()=>restore(dir),/mixed/);assert.deepEqual(snapshot(),before);
  seed();writeFileSync(join(dir,'.git'),'gitdir: forbidden');before=snapshot();assert.throws(()=>restore(dir),/Git checkout/);assert.deepEqual(snapshot(),before);
 }finally{rmSync(dir,{recursive:true,force:true});}
});
